#!/usr/bin/env bash
# ============================================================
#  clean.sh -- remove files GENERATED by ./configure and builds.
#
#  Deletes (never touches the templates):
#    Makefile, CMakeLists.txt, config.vars   <- configure output
#    build/ dist/ build-cmake/               <- build artifacts
#    *.so *.o *.a *.tmp *.act                <- stray artifacts
#    __pycache__                             <- python bindings
#
#  After running, the tree is pristine-source again:
#    ./configure && make && make test
# ============================================================
set -euo pipefail
cd "$(dirname "$0")"

removed=0
rm_one() {
    if [ -e "$1" ]; then
        rm -rf "$1"
        echo "  removed  $1"
        removed=$((removed + 1))
    fi
}

echo "clean.sh: removing generated files..."

# configure 产物 (模板 .in 保留)
rm_one Makefile
rm_one CMakeLists.txt
rm_one config.vars

# 构建产物
rm_one build
rm_one dist
rm_one build-cmake

# 零散产物
for f in libactivation.so libactivation_jni.so; do
    rm_one "$f"
done
rm_one bindings/java/build
rm_one bindings/rust/target
rm_one bindings/csharp/build
rm_one bindings/wasm/dist
rm_one crypto/build
rm_one crypto/dist
find . -name '__pycache__' -type d -exec rm -rf {} + 2>/dev/null || true
find . -name '*.class' -delete 2>/dev/null || true
find . -name '*.jar' -delete 2>/dev/null || true
find . -name 'libactivation_jni.so' -delete 2>/dev/null || true
find . -name 'activation_jni.dll' -delete 2>/dev/null || true
find . -name 'demo_kt.jar' -delete 2>/dev/null || true
find . -name '*.d' -delete 2>/dev/null || true
find . -maxdepth 1 \( -name '*.tmp' -o -name '*.act' -o -name '*.o' -o -name '*.a' \) \
    -delete 2>/dev/null || true

echo "done ($removed generated paths removed; templates intact)."
echo "rebuild with: ./configure && make && make test"
